insert into public.products (slug, name, category_slug, price_cents, compare_at_cents, badges, blurb, description, engine_size, specs, box_contents, features, image, featured, in_stock) values
  ('viper-special-edition-tgv-mini-trike', '“Viper” Special Edition TGV Mini Trike', 'mini-trikes', 110000, 120000, '["SALE","SPECIAL EDITION"]'::jsonb, 'Custom Build • Worldwide Ship', 'The Viper Special Edition is engineered for the adrenaline seeker. Featuring a reinforced TGV red-coated frame, oversized ProTaper bars, and a high-output 200cc engine, this machine delivers brutal performance on any terrain.', '200CC', '[{"label":"Engine Type","value":"200cc 6.5HP 4-Stroke"},{"label":"Top Speed","value":"45 MPH (Restricted)"},{"label":"Frame Material","value":"Reinforced TIG-Welded Steel"},{"label":"Brake System","value":"Front Hydraulic Disc"},{"label":"Drive Train","value":"Heavy-Duty Centrifugal Clutch"}]'::jsonb, '["Fully Assembled Viper","2x Replacement Sleeves","Maintenance Tool Kit","10% Coupon BIKEMIKE26"]'::jsonb, '[{"title":"Handcrafted Precision","text":"Each Viper unit is individually assembled and stress-tested in our California facility."},{"title":"200cc Adrenaline","text":"High-torque 4-stroke engine modified for maximum throttle response and drift stability."},{"title":"Custom Sleeves","text":"Proprietary PVC rear wheel sleeves designed for consistent sliding and long-term durability."}]'::jsonb, '/images/product-viper.svg', true, true),
  ('200cc-drift-trike-go-kart', '200CC Drift Trike Go-Kart', 'drift-karts', 139900, 150000, '["SALE"]'::jsonb, '4-Stroke • Upgraded Sleeves', 'A drift-first go-kart built around a torquey 200cc 4-stroke and upgraded rear sleeves. Low center of gravity, wide stance, and a chromoly-reinforced frame make it the benchmark for controlled slides.', '200CC', '[{"label":"Engine Type","value":"200cc 4-Stroke"},{"label":"Top Speed","value":"40 MPH"},{"label":"Frame Material","value":"Chromoly Steel"},{"label":"Brake System","value":"Rear Hydraulic Disc"},{"label":"Drive Train","value":"Centrifugal Clutch"}]'::jsonb, '["Fully Assembled Kart","Upgraded Drift Sleeves (Installed)","Maintenance Tool Kit"]'::jsonb, '[{"title":"Slide Geometry","text":"Wide rear track and low seat height tuned for maximum lateral G-force."},{"title":"4-Stroke Torque","text":"Instant low-end grunt that breaks traction on demand."},{"title":"Upgraded Sleeves","text":"Ships with our high-durability PVC drift sleeves pre-installed."}]'::jsonb, '/images/product-drift-kart.svg', true, true),
  ('212cc-monster-minibike', '212cc Monster Minibike', 'mini-bikes', 65000, 69900, '["60MPH"]'::jsonb, 'Raw Power • Terrain Ready', 'The Monster Minibike pairs a 212cc engine with knobby all-terrain tires and a beefed-up suspension fork. Sixty miles per hour of raw, unfiltered power in a frame you can throw in a truck bed.', '212CC', '[{"label":"Engine Type","value":"212cc 4-Stroke"},{"label":"Top Speed","value":"60 MPH"},{"label":"Frame Material","value":"Cold-Rolled Steel"},{"label":"Brake System","value":"Front & Rear Disc"},{"label":"Tires","value":"19\" Knobby All-Terrain"}]'::jsonb, '["Minibike (90% Assembled)","Assembly Hardware Kit","Owner''s Manual"]'::jsonb, '[{"title":"Raw Power","text":"212cc of torque tuned for hills, trails, and everything between."},{"title":"Terrain Ready","text":"Knobby tires and long-travel fork eat gravel, dirt, and mud."},{"title":"Truck-Bed Size","text":"Compact frame loads solo and stores anywhere."}]'::jsonb, '/images/product-minibike.svg', true, true),
  ('200cc-go-kart-dune-buggy', '200CC Go Kart Dune Buggy', 'quad-bikes', 129900, 150000, '["BLACK FRIDAY"]'::jsonb, 'Adult/Kids Sizes • Black Finish', 'A go-anywhere dune buggy with full roll cage, bucket seat, and a murdered-out black finish. Available in adult and kids sizing so the whole crew can ride.', '200CC', '[{"label":"Engine Type","value":"200cc 4-Stroke"},{"label":"Top Speed","value":"35 MPH"},{"label":"Frame Material","value":"Welded Steel Roll Cage"},{"label":"Brake System","value":"Hydraulic Disc"},{"label":"Seating","value":"Adjustable Bucket Seat"}]'::jsonb, '["Assembled Buggy","Safety Harness","Tool Kit"]'::jsonb, '[{"title":"Full Roll Cage","text":"Welded steel cage with padded harness points for real protection."},{"title":"Two Sizes","text":"Adult and kids frames share the same rugged drivetrain."},{"title":"Black Finish","text":"Powder-coated matte black that shrugs off rock chips."}]'::jsonb, '/images/product-dune-buggy.svg', true, true),
  ('200cc-quad-black', '200cc Quad - Black', 'quad-bikes', 129900, 150000, '["ALL-TERRAIN"]'::jsonb, 'Four Wheels • Zero Compromise', 'Our flagship quad in stealth black. A 200cc thumper, dual A-arm front suspension, and racks front and rear make it as happy hauling gear as it is tearing up trails.', '200CC', '[{"label":"Engine Type","value":"200cc 4-Stroke"},{"label":"Top Speed","value":"38 MPH"},{"label":"Suspension","value":"Dual A-Arm Front"},{"label":"Brake System","value":"Hydraulic Disc"},{"label":"Racks","value":"Front & Rear Steel"}]'::jsonb, '["Assembled Quad","Battery & Charger","Tool Kit"]'::jsonb, '[{"title":"All-Terrain","text":"Aggressive tread and ground clearance for mud, sand, and rock."},{"title":"Utility Ready","text":"Steel racks rated for 66 lbs of gear, tools, or firewood."},{"title":"Electric Start","text":"Turn-key ignition with backup pull start."}]'::jsonb, '/images/product-quad.svg', false, true),
  ('drift-sleeve-master-kit', 'Drift Sleeve Master Kit', 'spare-parts', 8500, null, '[]'::jsonb, 'Consistent Slides • Longer Life', 'The same proprietary PVC sleeves we fit to every Viper, packaged as a complete replacement kit with hardware. Fits all Go Cart Grip drift trikes and karts.', 'N/A', '[{"label":"Material","value":"High-Density PVC"},{"label":"Fitment","value":"All TN Drift Models"},{"label":"Contents","value":"2x Sleeves + Hardware"},{"label":"Install Time","value":"~20 Minutes"}]'::jsonb, '["2x Drift Sleeves","Retainer Hardware","Install Guide"]'::jsonb, '[{"title":"Consistent Slides","text":"Uniform wall thickness for predictable breakaway every run."},{"title":"Long-Term Durability","text":"Outlasts barrel-cut sleeves by 3x in abrasion testing."},{"title":"Tool-Light Install","text":"Swap both sleeves with a single hex key."}]'::jsonb, '/images/product-sleeve-kit.svg', false, true),
  ('venom-v3-trike', 'Venom V3 Trike', 'mini-trikes', 189900, null, '["NEW RELEASE"]'::jsonb, '212cc Staged • Hydraulic Disc', 'The third generation of our staged-engine flagship. The Venom V3 runs a 212cc staged build pushing 55 MPH, with hydraulic disc braking and a frame designed for full-lean drifting.', '212CC', '[{"label":"Engine","value":"212cc Staged"},{"label":"Top Speed","value":"55 MPH"},{"label":"Brakes","value":"Hydraulic Disc"},{"label":"Frame Material","value":"TIG-Welded Chromoly"},{"label":"Drive Train","value":"Performance Clutch"}]'::jsonb, '["Fully Assembled Venom V3","Spare Sleeve Set","Maintenance Tool Kit"]'::jsonb, '[{"title":"Staged Engine","text":"Ported head, performance carb, and open exhaust from the factory."},{"title":"55 MPH","text":"The fastest production trike we have ever shipped."},{"title":"Race Geometry","text":"Steeper head angle for razor-sharp turn-in."}]'::jsonb, '/images/product-venom.svg', false, true),
  ('scorpion-kart', 'Scorpion Kart', 'drift-karts', 165000, null, '[]'::jsonb, '145 LBS • Chain-Driven', 'A featherweight chain-driven kart built for tight circuits. At 145 lbs the Scorpion changes direction faster than anything in its class.', '212CC', '[{"label":"Weight","value":"145 LBS"},{"label":"Drive","value":"Chain-Driven"},{"label":"Engine","value":"212cc 4-Stroke"},{"label":"Brake System","value":"Rear Disc"}]'::jsonb, '["Assembled Kart","Chain Lube Kit","Tool Kit"]'::jsonb, '[{"title":"Featherweight","text":"145 lbs wet — the lightest kart in the fleet."},{"title":"Chain Drive","text":"Direct, mechanical power delivery with easy gearing swaps."},{"title":"Circuit Tuned","text":"Stiff frame and quick steering rack for tight courses."}]'::jsonb, '/images/product-scorpion.svg', false, true),
  ('nighthawk-500-quad', 'Nighthawk 500 Quad', 'quad-bikes', 249900, null, '["400CC"]'::jsonb, 'Big Bore • Trail Dominant', 'The biggest machine in the fleet. The Nighthawk''s 400cc big-bore engine and long-travel suspension are built for riders who outgrew everything else.', '400CC', '[{"label":"Engine Type","value":"400cc 4-Stroke"},{"label":"Top Speed","value":"55 MPH"},{"label":"Suspension","value":"Long-Travel Independent"},{"label":"Brake System","value":"Quad Hydraulic Disc"}]'::jsonb, '["Assembled Quad","Battery & Charger","Premium Tool Kit"]'::jsonb, '[{"title":"Big Bore","text":"400cc of usable torque across the whole rev range."},{"title":"Long Travel","text":"Independent suspension soaks up whoops at speed."},{"title":"Trail Dominant","text":"Full lighting kit for night runs."}]'::jsonb, '/images/product-nighthawk.svg', false, true),
  ('thunder-slide-drift-kart', 'Thunder Slide Drift Kart', 'drift-karts', 175000, null, '["ELECTRIC"]'::jsonb, 'Silent Torque • Instant Slide', 'Our first electric drift kart. Instant torque from a 3kW hub motor means the Thunder Slide breaks traction the moment you ask — silently.', 'ELECTRIC', '[{"label":"Motor","value":"3kW Brushless Hub"},{"label":"Top Speed","value":"35 MPH"},{"label":"Battery","value":"48V 20Ah Removable"},{"label":"Range","value":"~15 Miles Spirited"}]'::jsonb, '["Assembled Kart","48V Charger","Spare Sleeve Set"]'::jsonb, '[{"title":"Instant Torque","text":"100% torque at 0 RPM — slides start when you say so."},{"title":"Silent Running","text":"Ride at hours combustion machines can''t."},{"title":"Swap Battery","text":"Removable pack charges indoors in 3 hours."}]'::jsonb, '/images/product-thunder-slide.svg', false, true);
insert into public.testimonials (name, initials, role, quote, rating, sort_order) values
  ('Melissa T.', 'MT', 'Verified Buyer', 'I ordered the 200cc go-kart for my son''s birthday and the quality blew me away. The build feels solid, the engine runs smoothly, and assembly was simple thanks to the clear instructions. Definitely recommending this site!', 5, 0),
  ('Daniel Taylor', 'DT', 'Verified Buyer', 'I was nervous about ordering such a big item online, but gocartgrip.shop made it easy. Customer service answered all my questions about spare parts. Shipping was on time, and my quad started right up without a problem.', 5, 1),
  ('James B.', 'JB', 'Verified Buyer', 'If you''re looking for high-end drift equipment, this is it. The Viper is a beast and handles like a dream on the tarmac.', 5, 2),
  ('@gravel_king_99', 'GK', 'Rider', 'The build quality is insane. I''ve taken my mini bike through literal hell and it just keeps roaring.', 5, 3),
  ('Marcus R.', 'MR', 'Rider', 'Hands down the best drift trike on the market. Shipping was faster than the trike itself!', 5, 4),
  ('Jaxson Miller', 'JM', 'Purchased 2 weeks ago', 'Absolute monster of a machine. The low-end torque on the Viper is unmatched. Assembly was straightforward and the build quality feels military grade.', 5, 5);
