insert into public.site_settings (id, hero, announcements, contact, social) values
  (1, '{"kicker":"Handcrafted Performance","title":"Go Cart Grip:","accent":"Adrenaline","subtitle":"Engineered for the bold. Experience the raw energy of high-performance mini trikes and drift karts built for ultimate durability and speed.","primaryLabel":"Shop the Fleet","primaryHref":"/shop","secondaryLabel":"Custom Orders","secondaryHref":"/contact"}'::jsonb, '["Use the coupon BIKEMIKE26 for 10% discount","Black Friday Madness — up to 20% off","Now shipping worldwide"]'::jsonb, '{"phone":"+1 (916) 436-8303","email":"support@gocartgrip.shop","address":"4821 Throttle Way, Sacramento, CA 95814","hours":"Mon–Fri, 8am–5pm PT"}'::jsonb, '{"facebook":"https://facebook.com/gocartgrip","instagram":"https://instagram.com/gocartgrip","threads":"https://threads.net/@gocartgrip"}'::jsonb);
